def find_first_occurrence(arr, target):
    lo, hi = 0, len(arr) - 1
    result = -1

    while lo <= hi:
        mid = (lo + hi) // 2

        if arr[mid] == target:
            result = mid
            hi = mid - 1   # keep searching to the left
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1

    return result


if __name__ == "__main__":
    assert find_first_occurrence([2, 5, 5, 5, 6, 6, 8, 9, 9, 9], 5) == 1
